def mru_cache(maxsize=128, typed=False):
    class MRUCachable(dict):
        def __init__(self, maxsize, typed):
            self.maxsize = maxsize
            self.typed = typed
            self.queue = collections.deque()

        def __missing__(self, key):
            return self[key]

        def __setitem__(self, key, value):
            if self.typed:
                self.queue.append(key)
            super().__setitem__(key, value)
            if len(self) > self.maxsize:
                oldkey = self.queue.popleft()
                del self[oldkey]

    def wrapper(func):
        wfunc = MRUCachable(maxsize, typed)
        @wraps(func)
        def mru_wrapper(*args):
            key = args if typed else tuple(args)
            if key in wfunc:
                wfunc.queue.remove(key)
            else:
                wfunc.queue.append(key)
            return wfunc[key]
        return mru_wrapper
    return wrapper

