def deep_merge_nodes(nodes):
    result = dict()
    for key, value in nodes:
        # If there is a collision in the same key, merge the keys recursively
        if key in result:
            result_key = result[key]
            value_key = value
            if isinstance(result_key, dict) and isinstance(value_key, dict):
                result[key] = deep_merge_nodes( ((result_key, value_key),) )
                continue

            if isinstance(result_key, list) and isinstance(value_key, list):
                result[key] = result_key + value_key
                continue

            # If one of the values is not a dict or list, use the last value to win
            result[key] = value_key
        else:
            result[key] = value
    return result.values()

